<script setup>
import { computed, onMounted, ref } from 'vue'

const props=defineProps({token:{type:String,required:true},role:{type:String,required:true},users:{type:Array,default:()=>[]},menu:{type:Array,default:()=>[]},tables:{type:Array,default:()=>[]},ingredients:{type:Array,default:()=>[]},suppliers:{type:Array,default:()=>[]}})
const emit=defineEmits(['notice','refresh'])
const apiUrl=import.meta.env.VITE_API_URL||'/api'
async function api(path,options={}){const response=await fetch(`${apiUrl}${path}`,{...options,headers:{'Content-Type':'application/json',Authorization:`Bearer ${props.token}`,...(options.headers||{})}});const raw=await response.text();let data=null;try{data=raw?JSON.parse(raw):null}catch{}if(!response.ok)throw new Error(data?.error||`Lỗi máy chủ (${response.status})`);return data}
const money=v=>new Intl.NumberFormat('vi-VN').format(Number(v||0))+'đ'
const when=v=>v?new Date(v).toLocaleString('vi-VN'):'—'
const tabs=computed(()=>props.role==='owner'?['Đặt bàn','Bán hàng','Thu chi & hoàn tiền','Menu nâng cao','Khuyến mãi','Khách hàng','Mua hàng & lô kho','Lịch & chấm công','Báo cáo','Thuế & chi nhánh','Quyền chi tiết']:props.role==='manager'?['Đặt bàn','Bán hàng','Thu chi & hoàn tiền','Menu nâng cao','Khuyến mãi','Khách hàng','Mua hàng & lô kho','Lịch & chấm công','Báo cáo']:props.role==='cashier'?['Đặt bàn','Bán hàng','Thu chi & hoàn tiền','Khách hàng','Lịch & chấm công']:['Đặt bàn','Bán hàng','Lịch & chấm công'])
const tab=ref('Đặt bàn'),busy=ref(false)
const reservations=ref([]),waitlist=ref([]),orders=ref([]),cash=ref([]),refunds=ref([]),categories=ref([]),variants=ref([]),combos=ref([]),promotions=ref([]),customers=ref([]),people=ref([]),purchaseOrders=ref([]),lots=ref([]),balances=ref([]),supplierPayments=ref([]),schedules=ref([]),attendance=ref(null),attendanceReport=ref([]),report=ref(null),tax=ref({taxCode:'',invoiceName:'',invoiceEmail:'',vatRate:0,address:''}),stores=ref([]),storeReport=ref([]),permissionCatalog=ref([]),permissionUser=ref(''),permissionValues=ref({})
const reservation=ref({tableId:'',customerName:'',phone:'',guestCount:2,reservedAt:'',note:''}),waiting=ref({customerName:'',phone:'',guestCount:2,note:''})
const offsite=ref({orderType:'takeaway',customerName:'',customerPhone:'',deliveryAddress:'',fulfillmentAt:'',items:[{productId:'',quantity:1,note:''}]})
const movement=ref({type:'expense',amount:'',category:'',reason:''}),refund=ref({orderId:'',amount:'',method:'cash',reason:''}),mixed=ref({orderId:'',cash:0,bank_transfer:0,card:0,e_wallet:0})
const category=ref({name:'',position:0}),variant=ref({productId:'',name:'',priceDelta:0,position:0}),combo=ref({name:'',price:0,startsAt:'',endsAt:'',items:[{productId:'',quantity:1}]})
const productEdit=ref({id:'',name:'',price:0,categoryId:'',sku:''}),promotion=ref({id:'',code:'',name:'',type:'percent',value:0,minimumOrder:0,maximumDiscount:null,startsAt:null,endsAt:null,usageLimit:null,perCustomerLimit:null,isActive:true})
const split=ref({orderId:'',items:[]}),invoice=ref({orderId:'',buyerName:'',buyerTaxCode:'',buyerEmail:''}),invoices=ref([])
const customerId=ref(''),customerProfile=ref(null),points=ref({points:0,reason:'',expiresAt:''})
const po=ref({supplierId:'',expectedAt:'',note:'',items:[{ingredientId:'',quantity:1,unitCost:0}]}),lot=ref({ingredientId:'',lotCode:'',quantity:1,expiresAt:''}),supplierPayment=ref({supplierId:'',purchaseOrderId:'',amount:0,method:'bank_transfer',note:''})
const schedule=ref({userId:'',startsAt:'',endsAt:'',hourlyRate:0,note:''}),dates=ref({from:new Date(Date.now()-30*86400000).toISOString().slice(0,10),to:new Date().toISOString().slice(0,10)}),store=ref({code:'',name:'',address:''})
async function run(action,message){busy.value=true;try{await action();if(message)emit('notice',message)}catch(e){emit('notice',e.message)}finally{busy.value=false}}
async function load(){await run(async()=>{const tasks=[api('/reservations'),api('/waitlist'),api('/orders'),api('/schedules'),api('/attendance/current')];const [r,w,o,s,a]=await Promise.all(tasks);reservations.value=r;waitlist.value=w;orders.value=o;schedules.value=s;attendance.value=a;if(['owner','manager','cashier'].includes(props.role)){[cash.value,refunds.value,customers.value,invoices.value]=await Promise.all([api('/cash-movements'),api('/refunds'),api('/customers'),api('/e-invoices')])}if(['owner','manager'].includes(props.role)){[categories.value,variants.value,combos.value,promotions.value,purchaseOrders.value,lots.value,balances.value,supplierPayments.value,attendanceReport.value,report.value,people.value]=await Promise.all([api('/categories'),api('/product-variants'),api('/combos'),api('/promotions'),api('/purchase-orders'),api('/inventory/lots'),api('/supplier-balances'),api('/supplier-payments'),api('/attendance/report'),api(`/reports/advanced?from=${dates.value.from}&to=${dates.value.to}`),api('/staff-directory')])}if(props.role==='owner'){[tax.value,stores.value,storeReport.value,permissionCatalog.value]=await Promise.all([api('/tax-settings'),api('/stores'),api('/stores/report'),api('/permissions/catalog')])}},'')}
const mutate=(request,message)=>run(async()=>{await request();await load();emit('refresh')},message)
const addLine=(target,blank)=>target.push({...blank})
const removeLine=(target,index)=>{if(target.length>1)target.splice(index,1)}
function submitReservation(){mutate(()=>api('/reservations',{method:'POST',body:JSON.stringify({...reservation.value,tableId:reservation.value.tableId||null,guestCount:Number(reservation.value.guestCount),reservedAt:new Date(reservation.value.reservedAt).toISOString()})}),'Đã lưu lịch đặt bàn');reservation.value={tableId:'',customerName:'',phone:'',guestCount:2,reservedAt:'',note:''}}
function submitOffsite(){const body={...offsite.value,fulfillmentAt:offsite.value.fulfillmentAt?new Date(offsite.value.fulfillmentAt).toISOString():null,items:offsite.value.items.filter(x=>x.productId).map(x=>({productId:x.productId,quantity:Number(x.quantity),note:x.note,toppings:[],variantId:null}))};mutate(()=>api('/orders/offsite',{method:'POST',body:JSON.stringify(body)}),'Đã gửi đơn tới pha chế')}
function submitMixed(){const payments=['cash','bank_transfer','card','e_wallet'].map(method=>({method,amount:Number(mixed.value[method]||0),reference:null})).filter(x=>x.amount>0);mutate(()=>api(`/orders/${mixed.value.orderId}/mixed-payment`,{method:'POST',body:JSON.stringify({payments})}),'Đã thanh toán nhiều phương thức')}
function submitRefund(){mutate(()=>api(`/orders/${refund.value.orderId}/refund`,{method:'POST',body:JSON.stringify({...refund.value,amount:Number(refund.value.amount),orderId:undefined})}),'Đã ghi nhận hoàn tiền')}
function submitPo(){mutate(()=>api('/purchase-orders',{method:'POST',body:JSON.stringify({...po.value,supplierId:po.value.supplierId||null,expectedAt:po.value.expectedAt?new Date(po.value.expectedAt).toISOString():null,items:po.value.items.filter(x=>x.ingredientId).map(x=>({...x,quantity:Number(x.quantity),unitCost:Number(x.unitCost)}))})}),'Đã tạo đơn mua hàng')}
async function chooseCustomer(){if(!customerId.value)return;await run(async()=>{const data=await api(`/customers/${customerId.value}/profile`);data.customer.FullName=data.customer.FullName??data.customer.fullName;data.customer.Phone=data.customer.Phone??data.customer.phone;data.customer.Points=data.customer.Points??data.customer.points;data.customer.Tier=data.customer.Tier??data.customer.tier;customerProfile.value=data})}
async function loadPermissions(){if(!permissionUser.value)return;const rows=await api(`/users/${permissionUser.value}/permissions`);permissionValues.value=Object.fromEntries(permissionCatalog.value.map(x=>[x.key,rows.find(r=>r.key===x.key)?.isAllowed??true]))}
function selectProduct(){const p=props.menu.find(x=>x.id===productEdit.value.id);if(p)productEdit.value={id:p.id,name:p.name,price:p.price,categoryId:p.categoryId||categories.value[0]?.id||'',sku:p.sku||''}}
function saveProduct(){const {id,...body}=productEdit.value;mutate(()=>api(`/products/${id}`,{method:'PUT',body:JSON.stringify({...body,price:Number(body.price)})}),'Đã cập nhật món')}
function editPromotion(x){promotion.value={...x,startsAt:x.startsAt?.slice(0,16)||null,endsAt:x.endsAt?.slice(0,16)||null}}
function savePromotion(){const x=promotion.value;const body={...x,value:Number(x.value),minimumOrder:Number(x.minimumOrder),maximumDiscount:x.maximumDiscount===''?null:Number(x.maximumDiscount),usageLimit:x.usageLimit===''?null:Number(x.usageLimit),perCustomerLimit:x.perCustomerLimit===''?null:Number(x.perCustomerLimit),startsAt:x.startsAt||null,endsAt:x.endsAt||null};const request=x.id?api(`/promotions/${x.id}`,{method:'PUT',body:JSON.stringify(body)}):api('/promotions',{method:'POST',body:JSON.stringify(body)});mutate(()=>request,x.id?'Đã cập nhật khuyến mãi':'Đã tạo khuyến mãi')}
async function loadSplitOrder(){if(!split.value.orderId)return;const detail=await api(`/orders/${split.value.orderId}`);split.value.items=detail.items.filter(x=>x.status==='sent').map(x=>({itemId:x.id,name:x.name||x.productName,max:x.quantity,quantity:0}))}
function submitSplit(){const items=split.value.items.filter(x=>Number(x.quantity)>0).map(x=>({itemId:x.itemId,quantity:Number(x.quantity)}));mutate(()=>api(`/orders/${split.value.orderId}/split`,{method:'POST',body:JSON.stringify({items})}),'Đã tách hóa đơn')}
onMounted(load)
</script>

<template>
  <section class="suite panel-card">
    <div class="suite-head"><div><p class="eyebrow">TRUNG TÂM QUẢN LÝ</p><h2>Nghiệp vụ mở rộng</h2><small>Dữ liệu thật, đồng bộ chung giữa phục vụ, pha chế và thu ngân.</small></div><button class="ghost" :disabled="busy" @click="load">↻ Làm mới</button></div>
    <div class="suite-tabs"><button v-for="name in tabs" :key="name" :class="{active:tab===name}" @click="tab=name">{{ name }}</button></div>

    <div v-if="tab==='Đặt bàn'" class="suite-grid">
      <form class="suite-card form-grid" @submit.prevent="submitReservation"><h3>Đặt bàn trước</h3><input v-model="reservation.customerName" placeholder="Tên khách" required><input v-model="reservation.phone" placeholder="Số điện thoại" required><input v-model.number="reservation.guestCount" type="number" min="1" placeholder="Số khách"><input v-model="reservation.reservedAt" type="datetime-local" required><select v-model="reservation.tableId"><option value="">Chưa xếp bàn</option><option v-for="t in tables" :key="t.id" :value="t.id">{{ t.name }}</option></select><input v-model="reservation.note" placeholder="Ghi chú"><button>Thêm lịch đặt</button></form>
      <form class="suite-card form-grid" @submit.prevent="mutate(()=>api('/waitlist',{method:'POST',body:JSON.stringify({...waiting,guestCount:Number(waiting.guestCount)})}),'Đã thêm khách chờ')"><h3>Danh sách khách chờ</h3><input v-model="waiting.customerName" placeholder="Tên khách" required><input v-model="waiting.phone" placeholder="Số điện thoại"><input v-model.number="waiting.guestCount" type="number" min="1"><input v-model="waiting.note" placeholder="Ghi chú"><button>Thêm khách chờ</button></form>
      <div class="suite-card wide"><h3>Lịch hôm nay</h3><div v-for="x in reservations" :key="x.id" class="suite-row"><span><b>{{ x.customerName }}</b><small>{{ x.phone }} · {{ x.guestCount }} khách · {{ x.tableName }}</small></span><time>{{ when(x.reservedAt) }}</time><select :value="x.status" @change="mutate(()=>api(`/reservations/${x.id}/status`,{method:'PATCH',body:JSON.stringify({status:$event.target.value})}),'Đã cập nhật')"><option value="booked">Đã đặt</option><option value="confirmed">Đã xác nhận</option><option value="arrived">Đã đến</option><option value="seated">Đã xếp bàn</option><option value="cancelled">Đã hủy</option><option value="no_show">Không đến</option></select></div><div v-for="x in waitlist" :key="x.id" class="suite-row"><span><b>Chờ: {{ x.customerName }}</b><small>{{ x.guestCount }} khách · {{ x.phone }}</small></span><button @click="mutate(()=>api(`/waitlist/${x.id}/seat`,{method:'PATCH'}),'Đã xếp bàn')">Đã có bàn</button></div></div>
    </div>

    <div v-else-if="tab==='Bán hàng'" class="suite-grid">
      <form class="suite-card form-grid wide" @submit.prevent="submitOffsite"><h3>Đơn mang đi / giao hàng</h3><select v-model="offsite.orderType"><option value="takeaway">Mang đi</option><option value="delivery">Giao hàng</option></select><input v-model="offsite.customerName" placeholder="Tên khách"><input v-model="offsite.customerPhone" placeholder="Số điện thoại"><input v-if="offsite.orderType==='delivery'" v-model="offsite.deliveryAddress" placeholder="Địa chỉ giao hàng" required><input v-model="offsite.fulfillmentAt" type="datetime-local"><div v-for="(x,i) in offsite.items" :key="i" class="line"><select v-model="x.productId" required><option value="">Chọn món</option><option v-for="p in menu" :key="p.id" :value="p.id">{{ p.name }} · {{ money(p.price) }}</option></select><input v-model.number="x.quantity" type="number" min="1"><input v-model="x.note" placeholder="Ghi chú"><button type="button" @click="removeLine(offsite.items,i)">×</button></div><button type="button" class="ghost" @click="addLine(offsite.items,{productId:'',quantity:1,note:''})">+ Thêm món</button><button>Gửi đơn</button></form>
      <form v-if="['owner','manager','cashier'].includes(role)" class="suite-card form-grid" @submit.prevent="submitMixed"><h3>Thanh toán kết hợp</h3><select v-model="mixed.orderId" required><option value="">Chọn đơn chưa thanh toán</option><option v-for="o in orders.filter(x=>!['paid','cancelled'].includes(x.status))" :key="o.id" :value="o.id">#{{ o.orderNumber }} · {{ o.tableName }} · {{ money(o.total) }}</option></select><input v-model.number="mixed.cash" type="number" min="0" placeholder="Tiền mặt"><input v-model.number="mixed.bank_transfer" type="number" min="0" placeholder="Chuyển khoản"><input v-model.number="mixed.card" type="number" min="0" placeholder="Thẻ"><input v-model.number="mixed.e_wallet" type="number" min="0" placeholder="Ví điện tử"><button>Chốt thanh toán</button></form>
      <form class="suite-card form-grid" @submit.prevent="submitSplit"><h3>Tách hóa đơn</h3><select v-model="split.orderId" required @change="loadSplitOrder"><option value="">Chọn đơn đang mở</option><option v-for="o in orders.filter(x=>!['paid','cancelled'].includes(x.status))" :key="o.id" :value="o.id">#{{ o.orderNumber }} · {{ o.tableName }}</option></select><label v-for="x in split.items" :key="x.itemId" class="split-line"><span>{{ x.name }} · tối đa {{ x.max }}</span><input v-model.number="x.quantity" type="number" min="0" :max="x.max"></label><button :disabled="!split.items.length">Tạo hóa đơn tách</button></form>
    </div>

    <div v-else-if="tab==='Thu chi & hoàn tiền'" class="suite-grid">
      <form class="suite-card form-grid" @submit.prevent="mutate(()=>api('/cash-movements',{method:'POST',body:JSON.stringify({...movement,amount:Number(movement.amount)})}),'Đã lưu phiếu thu/chi')"><h3>Phiếu thu / chi trong ca</h3><select v-model="movement.type"><option value="cash_in">Thu khác</option><option value="cash_out">Chi tiền mặt</option><option value="expense">Chi phí</option></select><input v-model.number="movement.amount" type="number" min="1" placeholder="Số tiền" required><input v-model="movement.category" placeholder="Nhóm chi phí"><input v-model="movement.reason" placeholder="Nội dung" required><button>Lưu phiếu</button></form>
      <form class="suite-card form-grid" @submit.prevent="submitRefund"><h3>Hoàn tiền giao dịch</h3><select v-model="refund.orderId" required><option value="">Chọn đơn đã thanh toán</option><option v-for="o in orders.filter(x=>x.status==='paid')" :key="o.id" :value="o.id">#{{ o.orderNumber }} · {{ money(o.total) }}</option></select><input v-model.number="refund.amount" type="number" min="1" placeholder="Số tiền hoàn" required><select v-model="refund.method"><option value="cash">Tiền mặt</option><option value="bank_transfer">Chuyển khoản</option><option value="card">Thẻ</option><option value="e_wallet">Ví điện tử</option></select><input v-model="refund.reason" placeholder="Lý do hoàn" required><button>Ghi nhận hoàn tiền</button></form>
      <form class="suite-card form-grid" @submit.prevent="mutate(()=>api(`/orders/${invoice.orderId}/e-invoice`,{method:'POST',body:JSON.stringify({buyerName:invoice.buyerName,buyerTaxCode:invoice.buyerTaxCode,buyerEmail:invoice.buyerEmail})}),'Đã lập dữ liệu hóa đơn điện tử')"><h3>Lập hóa đơn điện tử</h3><select v-model="invoice.orderId" required><option value="">Chọn đơn đã thanh toán</option><option v-for="o in orders.filter(x=>x.status==='paid'&&!invoices.some(i=>i.orderId===x.id))" :key="o.id" :value="o.id">#{{ o.orderNumber }} · {{ money(o.total) }}</option></select><input v-model="invoice.buyerName" placeholder="Tên người mua / đơn vị"><input v-model="invoice.buyerTaxCode" placeholder="Mã số thuế"><input v-model="invoice.buyerEmail" type="email" placeholder="Email nhận hóa đơn"><button>Lập hóa đơn</button></form>
      <div class="suite-card wide"><h3>Sổ quỹ gần đây</h3><div v-for="x in cash" :key="x.id" class="suite-row"><span><b>{{ x.reason }}</b><small>{{ x.category||x.type }} · {{ x.staff }}</small></span><strong :class="{negative:x.type!=='cash_in'}">{{ x.type==='cash_in'?'+':'−' }}{{ money(x.amount) }}</strong><time>{{ when(x.createdAt) }}</time></div><div v-for="x in refunds" :key="x.id" class="suite-row"><span><b>Hoàn đơn #{{ x.orderNumber }}</b><small>{{ x.reason }} · {{ x.staff }}</small></span><strong class="negative">−{{ money(x.amount) }}</strong><time>{{ when(x.createdAt) }}</time></div></div>
    </div>

    <div v-else-if="tab==='Menu nâng cao'" class="suite-grid">
      <form class="suite-card form-grid" @submit.prevent="saveProduct"><h3>Sửa món bán</h3><select v-model="productEdit.id" required @change="selectProduct"><option value="">Chọn món cần sửa</option><option v-for="p in menu" :key="p.id" :value="p.id">{{ p.name }}</option></select><input v-model="productEdit.name" placeholder="Tên món" required><input v-model.number="productEdit.price" type="number" min="0" placeholder="Giá bán"><select v-model="productEdit.categoryId" required><option value="">Danh mục</option><option v-for="x in categories" :key="x.id" :value="x.id">{{ x.name }}</option></select><input v-model="productEdit.sku" placeholder="Mã SKU"><button>Lưu món</button></form>
      <form class="suite-card form-grid" @submit.prevent="mutate(()=>api('/categories',{method:'POST',body:JSON.stringify({...category,position:Number(category.position)})}),'Đã thêm danh mục')"><h3>Danh mục món</h3><input v-model="category.name" placeholder="Tên danh mục" required><input v-model.number="category.position" type="number" min="0" placeholder="Thứ tự"><button>Thêm danh mục</button><div v-for="x in categories" :key="x.id" class="suite-row"><b>{{ x.name }}</b><button type="button" class="danger" @click="mutate(()=>api(`/categories/${x.id}`,{method:'DELETE'}),'Đã ẩn danh mục')">Ẩn</button></div></form>
      <form class="suite-card form-grid" @submit.prevent="mutate(()=>api('/product-variants',{method:'POST',body:JSON.stringify({...variant,priceDelta:Number(variant.priceDelta),position:Number(variant.position)})}),'Đã thêm lựa chọn')"><h3>Size / biến thể món</h3><select v-model="variant.productId" required><option value="">Chọn món</option><option v-for="p in menu" :key="p.id" :value="p.id">{{ p.name }}</option></select><input v-model="variant.name" placeholder="Ví dụ: Size L" required><input v-model.number="variant.priceDelta" type="number" placeholder="Giá cộng thêm"><button>Thêm lựa chọn</button><div v-for="x in variants" :key="x.id" class="suite-row"><span><b>{{ x.name }}</b><small>+{{ money(x.priceDelta) }}</small></span><button type="button" class="danger" @click="mutate(()=>api(`/product-variants/${x.id}`,{method:'DELETE'}),'Đã ẩn lựa chọn')">Ẩn</button></div></form>
      <form class="suite-card form-grid wide" @submit.prevent="mutate(()=>api('/combos',{method:'POST',body:JSON.stringify({...combo,price:Number(combo.price),startsAt:combo.startsAt||null,endsAt:combo.endsAt||null,items:combo.items.filter(x=>x.productId).map(x=>({...x,quantity:Number(x.quantity)}))})}),'Đã tạo combo')"><h3>Combo bán hàng</h3><input v-model="combo.name" placeholder="Tên combo" required><input v-model.number="combo.price" type="number" min="0" placeholder="Giá combo"><div v-for="(x,i) in combo.items" :key="i" class="line"><select v-model="x.productId"><option value="">Chọn món</option><option v-for="p in menu" :key="p.id" :value="p.id">{{ p.name }}</option></select><input v-model.number="x.quantity" type="number" min="1"><button type="button" @click="removeLine(combo.items,i)">×</button></div><button type="button" class="ghost" @click="addLine(combo.items,{productId:'',quantity:1})">+ Thêm món</button><button>Tạo combo</button><div v-for="x in combos" :key="x.id" class="suite-row"><span><b>{{ x.name }}</b><small>{{ money(x.price) }}</small></span><button type="button" class="danger" @click="mutate(()=>api(`/combos/${x.id}`,{method:'DELETE'}),'Đã ẩn combo')">Ẩn</button></div></form>
    </div>

    <div v-else-if="tab==='Khách hàng'" class="suite-grid"><div class="suite-card"><h3>Hồ sơ khách hàng</h3><select v-model="customerId" @change="chooseCustomer"><option value="">Chọn khách hàng</option><option v-for="x in customers" :key="x.id" :value="x.id">{{ x.name }} · {{ x.phone }}</option></select><template v-if="customerProfile"><h3>{{ customerProfile.customer.FullName }}</h3><p>{{ customerProfile.customer.Phone }} · {{ customerProfile.customer.Points }} điểm · Hạng {{ customerProfile.customer.Tier }}</p><div v-for="x in customerProfile.orders" :key="x.id" class="suite-row"><span>Đơn #{{ x.orderNumber }}</span><b>{{ money(x.total) }}</b></div></template></div><form v-if="customerProfile&&['owner','manager'].includes(role)" class="suite-card form-grid" @submit.prevent="mutate(()=>api(`/customers/${customerId}/points`,{method:'POST',body:JSON.stringify({...points,points:Number(points.points),expiresAt:points.expiresAt||null})}),'Đã điều chỉnh điểm')"><h3>Điều chỉnh điểm</h3><input v-model.number="points.points" type="number" placeholder="Số điểm (+ hoặc -)" required><input v-model="points.reason" placeholder="Lý do" required><input v-model="points.expiresAt" type="date"><button>Lưu điểm</button></form></div>

    <div v-else-if="tab==='Khuyến mãi'" class="suite-grid"><form class="suite-card form-grid" @submit.prevent="savePromotion"><h3>{{ promotion.id?'Sửa khuyến mãi':'Tạo khuyến mãi' }}</h3><input v-model="promotion.code" placeholder="Mã" required><input v-model="promotion.name" placeholder="Tên chương trình" required><select v-model="promotion.type"><option value="percent">Phần trăm</option><option value="fixed">Số tiền</option></select><input v-model.number="promotion.value" type="number" min="1" placeholder="Giá trị"><input v-model.number="promotion.minimumOrder" type="number" min="0" placeholder="Đơn tối thiểu"><input v-model.number="promotion.maximumDiscount" type="number" min="0" placeholder="Giảm tối đa"><input v-model.number="promotion.usageLimit" type="number" min="1" placeholder="Tổng lượt dùng"><input v-model.number="promotion.perCustomerLimit" type="number" min="1" placeholder="Lượt/khách"><button>Lưu khuyến mãi</button></form><div class="suite-card"><h3>Chương trình hiện có</h3><div v-for="x in promotions" :key="x.id" class="suite-row"><span><b>{{ x.code }} · {{ x.name }}</b><small>Đã dùng {{ x.usedCount }}{{ x.usageLimit?' / '+x.usageLimit:'' }} lượt</small></span><button @click="editPromotion(x)">Sửa</button><button :class="{danger:x.isActive}" @click="mutate(()=>api(`/promotions/${x.id}/status`,{method:'PATCH',body:JSON.stringify({isActive:!x.isActive})}),'Đã đổi trạng thái')">{{ x.isActive?'Tắt':'Bật' }}</button></div></div></div>

    <div v-else-if="tab==='Mua hàng & lô kho'" class="suite-grid">
      <form class="suite-card form-grid wide" @submit.prevent="submitPo"><h3>Đơn mua nguyên liệu</h3><select v-model="po.supplierId"><option value="">Chọn nhà cung cấp</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{ s.name }}</option></select><input v-model="po.expectedAt" type="date"><input v-model="po.note" placeholder="Ghi chú"><div v-for="(x,i) in po.items" :key="i" class="line"><select v-model="x.ingredientId"><option value="">Nguyên liệu</option><option v-for="g in ingredients" :key="g.id" :value="g.id">{{ g.name }}</option></select><input v-model.number="x.quantity" type="number" step="0.001" min="0.001" placeholder="SL"><input v-model.number="x.unitCost" type="number" min="0" placeholder="Đơn giá"><button type="button" @click="removeLine(po.items,i)">×</button></div><button type="button" class="ghost" @click="addLine(po.items,{ingredientId:'',quantity:1,unitCost:0})">+ Dòng nguyên liệu</button><button>Tạo đơn mua</button></form>
      <form class="suite-card form-grid" @submit.prevent="mutate(()=>api('/inventory/lots',{method:'POST',body:JSON.stringify({...lot,quantity:Number(lot.quantity),expiresAt:lot.expiresAt||null})}),'Đã thêm lô nguyên liệu')"><h3>Lô & hạn sử dụng</h3><select v-model="lot.ingredientId" required><option value="">Chọn nguyên liệu</option><option v-for="g in ingredients" :key="g.id" :value="g.id">{{ g.name }}</option></select><input v-model="lot.lotCode" placeholder="Mã lô"><input v-model.number="lot.quantity" type="number" step="0.001" min="0.001"><input v-model="lot.expiresAt" type="date"><button>Lưu lô</button></form>
      <form class="suite-card form-grid" @submit.prevent="mutate(()=>api('/supplier-payments',{method:'POST',body:JSON.stringify({...supplierPayment,amount:Number(supplierPayment.amount),purchaseOrderId:supplierPayment.purchaseOrderId||null})}),'Đã ghi nhận trả nhà cung cấp')"><h3>Trả nhà cung cấp</h3><select v-model="supplierPayment.supplierId" required><option value="">Nhà cung cấp</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{ s.name }}</option></select><input v-model.number="supplierPayment.amount" type="number" min="1" placeholder="Số tiền"><select v-model="supplierPayment.method"><option value="bank_transfer">Chuyển khoản</option><option value="cash">Tiền mặt</option><option value="card">Thẻ</option></select><input v-model="supplierPayment.note" placeholder="Ghi chú"><button>Lưu thanh toán</button></form>
      <div class="suite-card wide"><h3>Công nợ & lô sắp hết hạn</h3><div v-for="x in balances" :key="x.supplierId" class="suite-row"><span><b>{{ x.supplier }}</b><small>Đã mua {{ money(x.purchased) }} · đã trả {{ money(x.paid) }}</small></span><strong :class="{negative:x.balance>0}">Còn {{ money(x.balance) }}</strong></div><div v-for="x in lots" :key="x.id" class="suite-row"><span><b>{{ x.ingredient }} · lô {{ x.lotCode||'—' }}</b><small>Còn {{ x.quantity }}</small></span><time>HSD {{ x.expiresAt?new Date(x.expiresAt).toLocaleDateString('vi-VN'):'Không có' }}</time></div></div>
    </div>

    <div v-else-if="tab==='Lịch & chấm công'" class="suite-grid"><div class="suite-card"><h3>Chấm công của tôi</h3><p>{{ attendance?'Đã vào ca lúc '+when(attendance.CheckInAt):'Chưa chấm công vào ca' }}</p><button v-if="!attendance" @click="mutate(()=>api('/attendance/check-in',{method:'POST'}),'Đã chấm công vào')">Chấm công vào</button><button v-else @click="mutate(()=>api('/attendance/check-out',{method:'POST'}),'Đã chấm công ra')">Chấm công ra</button></div><form v-if="['owner','manager'].includes(role)" class="suite-card form-grid" @submit.prevent="mutate(()=>api('/schedules',{method:'POST',body:JSON.stringify({...schedule,hourlyRate:Number(schedule.hourlyRate),startsAt:new Date(schedule.startsAt).toISOString(),endsAt:new Date(schedule.endsAt).toISOString()})}),'Đã xếp lịch')"><h3>Xếp lịch nhân viên</h3><select v-model="schedule.userId" required><option value="">Nhân viên</option><option v-for="u in users" :key="u.id" :value="u.id">{{ u.name }}</option></select><input v-model="schedule.startsAt" type="datetime-local" required><input v-model="schedule.endsAt" type="datetime-local" required><input v-model.number="schedule.hourlyRate" type="number" min="0" placeholder="Lương/giờ"><input v-model="schedule.note" placeholder="Ghi chú"><button>Thêm ca</button></form><div class="suite-card wide"><h3>Lịch làm</h3><div v-for="x in schedules" :key="x.id" class="suite-row"><span><b>{{ x.staff }}</b><small>{{ when(x.startsAt) }} → {{ when(x.endsAt) }}</small></span><strong>{{ money(x.hourlyRate) }}/giờ</strong><button v-if="['owner','manager'].includes(role)" class="danger" @click="mutate(()=>api(`/schedules/${x.id}`,{method:'DELETE'}),'Đã xóa lịch')">Xóa</button></div><div v-for="x in attendanceReport" :key="x.userId" class="suite-row"><span><b>{{ x.staff }}</b><small>{{ x.hours }} giờ</small></span><strong>Ước tính {{ money(x.estimatedSalary) }}</strong></div></div></div>

    <div v-else-if="tab==='Báo cáo'" class="suite-grid"><div class="suite-card wide"><div class="line"><input v-model="dates.from" type="date"><input v-model="dates.to" type="date"><button @click="load">Xem báo cáo</button></div><div v-if="report" class="report-metrics"><div><small>Doanh thu thuần</small><b>{{ money(report.sales) }}</b></div><div><small>Giá vốn</small><b>{{ money(report.cost) }}</b></div><div><small>Chi phí</small><b>{{ money(report.expenses) }}</b></div><div><small>Lợi nhuận gộp</small><b>{{ money(report.grossProfit) }}</b></div></div><h3>Món bán chạy</h3><div v-for="x in report?.products||[]" :key="x.name" class="suite-row"><b>{{ x.name }}</b><span>{{ x.quantity }} món</span><strong>{{ money(x.revenue) }}</strong></div><h3>Doanh thu theo ngày</h3><div v-for="x in report?.daily||[]" :key="x.date" class="suite-row"><b>{{ new Date(x.date).toLocaleDateString('vi-VN') }}</b><span>{{ x.orders }} đơn</span><strong>{{ money(x.revenue) }}</strong></div></div></div>

    <div v-else-if="tab==='Thuế & chi nhánh'" class="suite-grid"><form class="suite-card form-grid" @submit.prevent="mutate(()=>api('/tax-settings',{method:'PUT',body:JSON.stringify({...tax,vatRate:Number(tax.vatRate)})}),'Đã lưu cấu hình thuế')"><h3>Thông tin xuất hóa đơn</h3><input v-model="tax.taxCode" placeholder="Mã số thuế"><input v-model="tax.invoiceName" placeholder="Tên pháp nhân"><input v-model="tax.invoiceEmail" type="email" placeholder="Email nhận hóa đơn"><input v-model.number="tax.vatRate" type="number" min="0" max="100" step="0.1" placeholder="VAT %"><input v-model="tax.address" placeholder="Địa chỉ"><button>Lưu cấu hình</button></form><form class="suite-card form-grid" @submit.prevent="mutate(()=>api('/stores',{method:'POST',body:JSON.stringify(store)}),'Đã thêm chi nhánh')"><h3>Thêm chi nhánh</h3><input v-model="store.code" placeholder="Mã chi nhánh"><input v-model="store.name" placeholder="Tên chi nhánh" required><input v-model="store.address" placeholder="Địa chỉ"><button>Thêm chi nhánh</button></form><div class="suite-card wide"><h3>So sánh chi nhánh</h3><div v-for="x in stores" :key="x.id" class="suite-row"><span><b>{{ x.name }}</b><small>{{ x.code }} · {{ x.address }}</small></span><em>{{ x.isActive?'Đang hoạt động':'Đã tắt' }}</em><button @click="mutate(()=>api(`/stores/${x.id}/status`,{method:'PATCH',body:JSON.stringify({isActive:!x.isActive})}),'Đã cập nhật chi nhánh')">{{ x.isActive?'Tạm dừng':'Mở lại' }}</button></div><div v-for="x in storeReport" :key="x.id" class="suite-row"><b>{{ x.store }}</b><span>{{ x.orders }} đơn</span><strong>{{ money(x.revenue) }}</strong></div></div></div>

    <div v-else-if="tab==='Quyền chi tiết'" class="suite-grid"><div class="suite-card wide"><h3>Giới hạn riêng theo tài khoản</h3><p class="muted">Vai trò vẫn quyết định phạm vi chính. Các công tắc dưới đây dùng để thu hẹp thêm quyền của từng người.</p><select v-model="permissionUser" @change="loadPermissions"><option value="">Chọn tài khoản</option><option v-for="u in users" :key="u.id" :value="u.id">{{ u.name }} · {{ u.role }}</option></select><div v-if="permissionUser" class="permission-grid"><label v-for="p in permissionCatalog" :key="p.key"><input v-model="permissionValues[p.key]" type="checkbox">{{ p.name }}</label></div><button v-if="permissionUser" @click="mutate(()=>api(`/users/${permissionUser}/permissions`,{method:'PUT',body:JSON.stringify({items:permissionCatalog.map(p=>({key:p.key,isAllowed:!!permissionValues[p.key]}))})}),'Đã lưu quyền; tài khoản đó cần đăng nhập lại')">Lưu quyền chi tiết</button></div></div>
  </section>
</template>

